-- ============================================================
-- 005_seed_institutions.sql
-- Seed definitivo de unidades académicas de Córdoba
--
-- Fuente:
--   escuelas_cordoba - seed (2)(1).csv
--
-- Este archivo debe ejecutarse DESPUÉS de 004_refactor_db.sql.
--
-- El seed falla deliberadamente si ya existen instituciones,
-- para evitar una segunda ejecución accidental.
-- ============================================================

BEGIN;

-- ------------------------------------------------------------
-- Preflight
-- ------------------------------------------------------------

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM institutions) THEN
        RAISE EXCEPTION 'Seed cancelado: institutions no está vacía.';
    END IF;

    IF EXISTS (SELECT 1 FROM institution_levels) THEN
        RAISE EXCEPTION 'Seed cancelado: institution_levels no está vacía.';
    END IF;

    IF EXISTS (SELECT 1 FROM directivos) THEN
        RAISE EXCEPTION 'Seed cancelado: directivos no está vacío.';
    END IF;

    IF EXISTS (SELECT 1 FROM institution_directives) THEN
        RAISE EXCEPTION 'Seed cancelado: institution_directives no está vacío.';
    END IF;

    IF EXISTS (SELECT 1 FROM study_plans) THEN
        RAISE EXCEPTION 'Seed cancelado: study_plans no está vacío.';
    END IF;

    IF EXISTS (SELECT 1 FROM institution_study_plans) THEN
        RAISE EXCEPTION 'Seed cancelado: institution_study_plans no está vacío.';
    END IF;
END $$;

-- ------------------------------------------------------------
-- 1. institutions
-- ------------------------------------------------------------

