-- ------------------------------------------------------------
-- 2. institution_levels
--    La fuente contiene niveles como:
--      Común - Secundario
--      Jóvenes y Adultos - Primario
--      Especial
--
--    Se normaliza a:
--      modalidad + level
-- ------------------------------------------------------------

INSERT INTO institution_levels (
    id,
    institution_id,
    level,
    modalidad,
    empresa
)
SELECT
    gen_random_uuid()::text,
    i.id,
    CASE
        WHEN position(' - ' IN s.nivel_raw) > 0
            THEN substring(s.nivel_raw FROM position(' - ' IN s.nivel_raw) + 3)
        ELSE s.nivel_raw
    END AS level,
    CASE
        WHEN position(' - ' IN s.nivel_raw) > 0
            THEN substring(s.nivel_raw FROM 1 FOR position(' - ' IN s.nivel_raw) - 1)
        ELSE NULL
    END AS modalidad,
    NULL
FROM (
    SELECT * FROM (VALUES
