('140240400', 'Técnico mecánico'),
('140411400', 'Técnico en Programación'),
('140411400', 'Técnico mecánico'),
('140549200', 'Técnico en Programación'),
('140126200', 'Técnico mecánico'),
('140231100', 'Técnico mecánico'),
('140231100', 'Técnico minero'),
('140250600', 'Técnico mecánico'),
('140508100', 'Técnico mecánico'),
('140255800', 'Técnico minero'),
('140323700', 'Técnico minero'),
('140346300', 'Técnico minero'),
('140312200', 'Técnico químico')
    ) AS x(cue, nombre)
) AS source
JOIN institutions i
    ON i.cue = source.cue
JOIN institution_levels il
    ON il.institution_id = i.id
   AND il.level = 'Secundario'
JOIN study_plans sp
    ON sp.nombre = source.nombre;

-- ------------------------------------------------------------
-- 7. Validación final
-- ------------------------------------------------------------

DO $$
DECLARE
    n_institutions INTEGER;
    n_levels INTEGER;
    n_directivos INTEGER;
    n_directive_relations INTEGER;
    n_study_plans INTEGER;
    n_study_plan_relations INTEGER;
BEGIN
    SELECT COUNT(*) INTO n_institutions FROM institutions;
    SELECT COUNT(*) INTO n_levels FROM institution_levels;
    SELECT COUNT(*) INTO n_directivos FROM directivos;
    SELECT COUNT(*) INTO n_directive_relations FROM institution_directives;
    SELECT COUNT(*) INTO n_study_plans FROM study_plans;
    SELECT COUNT(*) INTO n_study_plan_relations FROM institution_study_plans;

    IF n_institutions <> 5489 THEN
        RAISE EXCEPTION 'Cantidad inesperada de institutions: % (esperado 5489)', n_institutions;
    END IF;

    IF n_levels <> 6260 THEN
        RAISE EXCEPTION 'Cantidad inesperada de institution_levels: % (esperado 6260)', n_levels;
    END IF;

    IF n_directivos <> 4572 THEN
        RAISE EXCEPTION 'Cantidad inesperada de directivos: % (esperado 4572)', n_directivos;
    END IF;

    IF n_directive_relations <> 5489 THEN
        RAISE EXCEPTION 'Cantidad inesperada de institution_directives: % (esperado 5489)', n_directive_relations;
    END IF;

    IF n_study_plans <> 72 THEN
        RAISE EXCEPTION 'Cantidad inesperada de study_plans: % (esperado 72)', n_study_plans;
    END IF;

    IF n_study_plan_relations <> 2328 THEN
        RAISE EXCEPTION 'Cantidad inesperada de institution_study_plans: % (esperado 2328)', n_study_plan_relations;
    END IF;
END $$;

COMMIT;
